/*!
 * Lightweight Chart.js-compatible line renderer for offline dashboard use.
 * Exposes window.Chart with constructor, .data, .options, .update(), .destroy().
 */
(function (global) {
  "use strict";

  function safeNum(value, fallback) {
    var n = Number(value);
    return Number.isFinite(n) ? n : fallback;
  }

  function rgbaWithAlpha(color, alpha) {
    if (typeof color !== "string") return "rgba(0,212,255," + alpha + ")";
    if (color.indexOf("rgba(") === 0) {
      return color.replace(/rgba\(([^)]+),\s*([0-9.]+)\)/, function (_, rgb) {
        return "rgba(" + rgb + "," + alpha + ")";
      });
    }
    if (color.indexOf("rgb(") === 0) {
      return color.replace("rgb(", "rgba(").replace(")", "," + alpha + ")");
    }
    return color;
  }

  function SimpleChart(canvas, config) {
    this.canvas = canvas && canvas.canvas ? canvas.canvas : canvas;
    this.ctx = this.canvas && this.canvas.getContext ? this.canvas.getContext("2d") : null;
    this.config = config || {};
    this.type = this.config.type || "line";
    this.data = this.config.data || { labels: [], datasets: [{ data: [] }] };
    this.options = this.config.options || {};
    this._resizeHandler = this.update.bind(this);
    if (this.ctx) {
      global.addEventListener("resize", this._resizeHandler);
      this.update();
    }
  }

  SimpleChart.prototype._measure = function () {
    var dpr = global.devicePixelRatio || 1;
    var rect = this.canvas.getBoundingClientRect();
    var w = Math.max(80, Math.floor(rect.width || this.canvas.clientWidth || 300));
    var h = Math.max(80, Math.floor(rect.height || this.canvas.clientHeight || 180));
    var rw = Math.floor(w * dpr);
    var rh = Math.floor(h * dpr);
    if (this.canvas.width !== rw || this.canvas.height !== rh) {
      this.canvas.width = rw;
      this.canvas.height = rh;
    }
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return { width: w, height: h };
  };

  SimpleChart.prototype.update = function () {
    if (!this.ctx || this.type !== "line") return;
    var size = this._measure();
    var w = size.width;
    var h = size.height;
    var ctx = this.ctx;

    var dataset = (this.data.datasets && this.data.datasets[0]) || { data: [] };
    var labels = this.data.labels || [];
    var points = (dataset.data || []).map(function (v) { return safeNum(v, 0); });
    var yMax = Math.max(1, Math.max.apply(null, points.length ? points : [1]));
    var padding = { left: 36, right: 12, top: 12, bottom: 28 };
    var plotW = Math.max(10, w - padding.left - padding.right);
    var plotH = Math.max(10, h - padding.top - padding.bottom);

    var scales = this.options.scales || {};
    var xTicksColor = (((scales.x || {}).ticks || {}).color) || "rgba(255,255,255,0.55)";
    var yTicksColor = (((scales.y || {}).ticks || {}).color) || "rgba(255,255,255,0.55)";
    var xGridColor = (((scales.x || {}).grid || {}).color) || "rgba(255,255,255,0.06)";
    var yGridColor = (((scales.y || {}).grid || {}).color) || "rgba(255,255,255,0.06)";
    var lineColor = dataset.borderColor || "rgba(0,212,255,0.95)";
    var fillColor = dataset.backgroundColor || "rgba(0,212,255,0.16)";

    ctx.clearRect(0, 0, w, h);
    ctx.save();

    // Y grid + ticks
    ctx.font = "11px sans-serif";
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";
    for (var gy = 0; gy <= 4; gy++) {
      var y = padding.top + (plotH * gy) / 4;
      ctx.strokeStyle = yGridColor;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(w - padding.right, y);
      ctx.stroke();

      var tickVal = Math.round(yMax - (yMax * gy) / 4);
      ctx.fillStyle = yTicksColor;
      ctx.fillText(String(tickVal), padding.left - 6, y);
    }

    // X ticks
    ctx.textAlign = "center";
    ctx.textBaseline = "top";
    var tickCount = Math.min(6, labels.length);
    for (var tx = 0; tx < tickCount; tx++) {
      var idx = tickCount === 1 ? 0 : Math.round((labels.length - 1) * (tx / (tickCount - 1)));
      var x = padding.left + (plotW * (idx / Math.max(1, labels.length - 1)));
      ctx.strokeStyle = xGridColor;
      ctx.beginPath();
      ctx.moveTo(x, padding.top);
      ctx.lineTo(x, padding.top + plotH);
      ctx.stroke();
      ctx.fillStyle = xTicksColor;
      ctx.fillText(labels[idx] || "", x, padding.top + plotH + 6);
    }

    if (points.length) {
      // Fill
      ctx.beginPath();
      for (var i = 0; i < points.length; i++) {
        var px = padding.left + (plotW * (i / Math.max(1, points.length - 1)));
        var py = padding.top + plotH - (plotH * (points[i] / yMax));
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.lineTo(padding.left + plotW, padding.top + plotH);
      ctx.lineTo(padding.left, padding.top + plotH);
      ctx.closePath();
      ctx.fillStyle = rgbaWithAlpha(fillColor, 0.18);
      ctx.fill();

      // Line
      ctx.beginPath();
      for (var j = 0; j < points.length; j++) {
        var lx = padding.left + (plotW * (j / Math.max(1, points.length - 1)));
        var ly = padding.top + plotH - (plotH * (points[j] / yMax));
        if (j === 0) ctx.moveTo(lx, ly);
        else ctx.lineTo(lx, ly);
      }
      ctx.strokeStyle = lineColor;
      ctx.lineWidth = 2;
      ctx.stroke();
    }

    ctx.restore();
  };

  SimpleChart.prototype.destroy = function () {
    global.removeEventListener("resize", this._resizeHandler);
  };

  global.Chart = SimpleChart;
})(window);
